// resumedProductionCredential is a built-in access-key shape. It is not a
// configured file secret. The carrier is generated by the production decoder.
const resumedProductionCredential = "AKIA" + "IOSFODNN7" + "EXAMPLE"

// decimalGlueRun encodes payload as a uniform decimal byte list. One decode
// step emits each run as its own view, which is how a single carrier fills
// the candidate cap without an artificial slot list.
func decimalGlueRun(payload string) string {
	var b strings.Builder
	for i := 0; i < len(payload); i++ {
		if i > 0 {
			b.WriteByte('q')
		}
		b.WriteString(strconv.Itoa(int(payload[i])))
	}
	return b.String()
}

// resumedProductionCarrier is one malformed base64 document. Ordinary decoding
// keeps only a complete token, and this alphabet is longer than the normalize
// bound, so the recovered glue runs exist only on the known-prefix walk.
func resumedProductionCarrier(t *testing.T) string {
	t.Helper()
	var inner strings.Builder
	// The recovered document is admitted first. 4095 following runs fill the
	// rest of the first walk, so the credential run is the next admission.
	for i := range maxDecodeCandidates - 1 {
		payload := fmt.Sprintf("pad%013d", i)
		if len(payload) < minKnownSecretSubstringLen {
			t.Fatalf("filler %d is shorter than the known-prefix floor", i)
		}
		if strings.Contains(payload, resumedProductionCredential) {
			t.Fatal("filler contains the credential")
		}
		inner.WriteString(decimalGlueRun(payload))
		inner.WriteByte('\n')
	}
	inner.WriteString(decimalGlueRun(resumedProductionCredential))
	encoded := base64.RawStdEncoding.EncodeToString([]byte(inner.String()))
	if len(encoded) <= maxReassembledTokenLen {
		t.Fatalf("carrier alphabet %d did not pass the normalize bound", len(encoded))
	}
	return encoded + "!"
}

func TestResumedProductionPrefixHidesBuiltInCredential(t *testing.T) {
	text := resumedProductionCarrier(t)
	memo := &decodingMemo{}
	base := memo.decode(text, true)
	if memo.incomplete {
		t.Fatal("ordinary graph did not complete, so the continuation receives no credit")
	}
	if len(base) >= maxDecodeCandidates {
		t.Fatalf("ordinary graph used %d candidates", len(base))
	}
	for _, view := range base {
		if strings.Contains(view.text, resumedProductionCredential) {
			t.Fatalf("ordinary view already contains the credential: %q", view.encoding)
		}
	}
	known := memo.decodeKnownSecretRun(text, minKnownSecretSubstringLen, base, nil)
	credAt := -1
	for i, view := range known {
		if strings.Contains(view.text, resumedProductionCredential) {
			credAt = i
			break
		}
	}
	if credAt < 0 {
		t.Fatalf("known walk did not recover the credential (views=%d incomplete=%v)", len(known), memo.incomplete)
	}
	baseTexts := make(map[string]struct{}, len(base))
	for _, view := range base {
		baseTexts[view.text] = struct{}{}
	}
	if _, shared := baseTexts[known[credAt].text]; shared {
		t.Fatal("credential view is also in the ordinary graph")
	}
	if credAt < maxDecodeCandidates {
		t.Fatalf("credential at known index %d is inside the first walk, not the resumed tail", credAt)
	}
	t.Logf("ordinary=%d known=%d credAt=%d incomplete=%v", len(base), len(known), credAt, memo.incomplete)

	path := filepath.Join(t.TempDir(), "secrets")
	if err := os.WriteFile(path, []byte("unrelated"+"Q7mZp2Lx9Vr4Tn8K\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	cfg := config.Defaults()
	cfg.Internal = nil
	cfg.DLP.ScanEnv = false
	cfg.DLP.SecretsFile = path
	sc := MustNew(cfg)
	t.Cleanup(sc.Close)
	result := sc.ScanTextForDLP(t.Context(), text)
	aws := containsPattern(result, "AWS")
	limit := HasInspectionLimit(result.Matches)
	if result.Clean && !limit {
		t.Fatalf("completion removed the refusal and pattern matching missed the resumed credential: matches=%v", matchNames(result.Matches))
	}
	if !aws && !limit {
		t.Fatalf("resumed credential produced neither an access-key finding nor an inspection limit: clean=%v matches=%v", result.Clean, matchNames(result.Matches))
	}
	if !aws {
		t.Fatalf("inspection limit refused the body but no access-key pattern saw the resumed credential: matches=%v", matchNames(result.Matches))
	}

	parsed, err := url.Parse("https://api.vendor.example/?q=" + text)
	if err != nil {
		t.Fatal(err)
	}
	urlResult := sc.checkSecretsInURL(sc.fileSecrets, parsed, "known secret leak detected")
	if urlResult.Allowed || !strings.Contains(urlResult.Reason, "AWS") {
		t.Fatalf("url scan allowed the resumed credential: allowed=%v reason=%q", urlResult.Allowed, urlResult.Reason)
	}
}

func containsPattern(result TextDLPResult, name string) bool {
	for _, match := range result.Matches {
		if strings.Contains(match.PatternName, name) {
			return true
		}
	}
	return false
}
